            ['id' => '114', 'data_keys' => 'feature_page.element', 'data_values' => '{"has_image":["1"],"title":"Unified Inbox","heading":"All your conversation in one place","description":"Easily manage and organize customer chats from WhatsApp in a centralized inbox.","benefits":"<ul class=\\"text-list\\">\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n         Instant switch to multiple whatsapp account\\r\\n    <\\/li>\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n        Instant access to all customer chats and data\\r\\n    <\\/li>\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n        Conversation tag, note & more\\r\\n    <\\/li>\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n        Seamless synchronization with the web platform\\r\\n    <\\/li>\\r\\n\\r\\n<\\/ul>","image":"684eb7859db891749989253.png"}', 'seo_content' => null, 'tempname' => 'basic', 'slug' => '', 'created_at' => '2025-03-27 06:02:44', 'updated_at' => '2025-06-15 12:07:36'],
            ['id' => '115', 'data_keys' => 'feature_page.element', 'data_values' => '{"has_image":["1"],"title":"Smart Automation","heading":"Save Time with Automation","description":"Automate repetitive tasks like sending welcome messages, follow-ups, and reminders with customizable workflows. Focus on what matters most\\u2014your customers.","benefits":"<ul class=\\"text-list\\">\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n         Easily set the welcome message for the each whatsapp account\\r\\n    <\\/li>\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n        Multiple chatbot support for the anytime response.\\r\\n    <\\/li>\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n        Send the scheduled message via scheduled campaign\\r\\n    <\\/li>\\r\\n<\\/ul>","image":"684eb373cfee11749988211.png"}', 'seo_content' => null, 'tempname' => 'basic', 'slug' => '', 'created_at' => '2025-03-27 06:12:41', 'updated_at' => '2025-06-15 11:50:11'],
            ['id' => '116', 'data_keys' => 'feature_page.element', 'data_values' => '{"has_image":["1"],"title":"Contact Segmentation","heading":"Organize Your Contacts Like Never Before","description":"Group your customers into segments with tags, labels, and filters. Tailor your communication to specific audiences for better results.","benefits":"<ul class=\\"text-list\\">\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n         Add the contact by manually\\r\\n    <\\/li>\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n        Import contact from your spreadsheet\\r\\n    <\\/li>\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n        Multiple contact supported\\r\\n    <\\/li>\\r\\n    <li class=\\"text-list__item\\">\\r\\n        <span class=\\"text-list__icon\\"> <i class=\\"las la-check\\"><\\/i> <\\/span>\\r\\n        Support multiple contact list\\r\\n    <\\/li>\\r\\n<\\/ul>","image":"684eb38a69c7b1749988234.png"}', 'seo_content' => null, 'tempname' => 'basic', 'slug' => '', 'created_at' => '2025-03-27 06:14:15', 'updated_at' => '2025-06-15 11:50:34'],
